parameters.jsCode:
const records = $input.all().map(item => item.json);

return [
  {
    json: {
      records
    }
  }
];

// Get records safely
const rawRecords = $input.first()?.json?.records;

// Ensure records is always an array
const records = Array.isArray(rawRecords)
  ? rawRecords
  : rawRecords
    ? [rawRecords]
    : [];

/*
 * Ensure the same newline and whitespace representation
 * is used for every dictionary key.
 */
const normalize = (value) => {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .replace(/\r\n/g, '\n') // Windows newline to Unix newline
    .replace(/\r/g, '\n')   // Remaining carriage returns
    .trim();                // Remove outer whitespace
};

const uniqueSet = new Set();

for (const rec of records) {
  const domain = normalize(rec?.domain);
  const degreeTrack = normalize(rec?.degree_track);
  const institution = normalize(rec?.institution);

  if (domain) {
    uniqueSet.add(domain);
  }

  if (degreeTrack) {
    uniqueSet.add(degreeTrack);
  }

  if (institution) {
    uniqueSet.add(institution);
  }

  if (Array.isArray(rec?.specializations)) {
    for (const specialization of rec.specializations) {
      const normalizedSpecialization = normalize(specialization);

      if (normalizedSpecialization) {
        uniqueSet.add(normalizedSpecialization);
      }
    }
  }

  if (Array.isArray(rec?.admission_options)) {
    for (const option of rec.admission_options) {
      const bacType = normalize(option?.bac_type);

      if (bacType) {
        uniqueSet.add(bacType);
      }
    }
  }
}

return Array.from(uniqueSet).map(text => ({
  json: {
    text
  }
}));

const input = $input.first().json;

const raw = input.text;
const batch = input.batch;

if (!raw || typeof raw !== 'string') {
  throw new Error('No LLM output found.');
}

if (!Array.isArray(batch)) {
  throw new Error('No batch found.');
}

const dict = {};

const lines = raw
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

for (const line of lines) {
  const parts = line.split('||');

  if (parts.length !== 3) {
    continue;
  }

  const index = Number(parts[0]);

  if (!Number.isInteger(index) || index < 0 || index >= batch.length) {
    continue;
  }

  dict[batch[index]] = {
    en: parts[1].trim(),
    fr: parts[2].trim()
  };
}

return [
  {
    json: {
      dict
    }
  }
];

function normalize(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

const batch = items
  .map(item => normalize(item.json.text))
  .filter(Boolean);

if (batch.length === 0) {
  throw new Error('The current batch is empty.');
}

const indexedInput = batch.map((text, index) => ({
  index,
  text
}));

return [
  {
    json: {
      batch,
      indexedInput,
      expectedCount: batch.length
    }
  }
];

const mergedDict = {};

for (const item of $input.all()) {
  const dict = item.json.dict || {};

  Object.assign(mergedDict, dict);
}

return [
  {
    json: mergedDict
  }
];

